const videoPrefix = "https://www.youtube.com/embed/watch?v=";
const embeddedVideo = document.getElementById("embedVideo");
const debugH1 = document.getElementById("debug");
const timerDisplay = document.getElementById("timerDisplay");
const timerInput = document.getElementById("timer");
const timerButton = document.getElementById("timerBtn");
const navTimer = document.querySelector(".navTimerDisplay");
let cachedIndex = 0;
let timerEnabled = false;

// 2. This code loads the IFrame Player API code asynchronously.
var tag = document.createElement('script');



tag.src = "https://www.youtube.com/iframe_api";
var firstScriptTag = document.getElementsByTagName('script')[0];
firstScriptTag.parentNode.insertBefore(tag, firstScriptTag);

// 3. This function creates an <iframe> (and YouTube player)
//    after the API code downloads.
var player;

doRandom();
const randomButton = document.querySelector(".randomBtn");
const randomHue = Math.floor(Math.random() * 360) + 1;
randomButton.style.setProperty('--base-color', `hsl(${randomHue}, 75.00%, 60.00%)`);
randomButton.style.setProperty('--hover-color', `hsl(${randomHue}, 75.00%, 75.00%)`);

function onYouTubeIframeAPIReady() {
    player = new YT.Player('player', {
        height: '800px',
        width: '100%',
        videoId: (loadVideo(cachedIndex)),
        host: 'https://www.youtube-nocookie.com',
        playerVars: {
        'playsinline': 1,
        'loop': 1,
        'origin': window.location.origin || `*`,
        
        },
        events: {
        'onReady': onPlayerReady,
        'onStateChange': onPlayerStateChange
        }
    });


    
}


// 4. The API will call this function when the video player is ready.
function onPlayerReady(event) {
    event.target.playVideo();

    goToRandomTime(player);
}

// 5. The API calls this function when the player's state changes.
//    The function indicates that when playing a video (state=1),
//    the player should play for six seconds and then stop.
var done = false;
function onPlayerStateChange(event) {
    /*if (event.data == YT.PlayerState.PLAYING && !done) {
            setTimeout(stopVideo, 6000);
            done = true;
    }
    */

    if (player.getPlayerState() === 0)
    {
        //automatically randomizes again if video ends.
        getRandomVideoAtRandomTime();

    }
}

function stopVideo() {
    player.stopVideo();
}

function doRandom()
{
    let randomIndex = Math.floor(Math.random() * videoIds.length);
    cachedIndex = randomIndex;
}

function loadVideo(index)
{
    return videoIds[index];
}
function loadTime(index)
{
    return (Math.floor(Math.random() * durations[index]));
}

function goToRandomTime(player)
{
    let randTime = Math.floor(Math.random() * durations[cachedIndex]);
    console.log(randTime);
    player.seekTo(randTime);
}

function getRandomVideoAtRandomTime()
{
    const randomHue = Math.floor(Math.random() * 360) + 1;
    randomButton.style.setProperty('--base-color', `hsl(${randomHue}, 75.00%, 60.00%)`);
    randomButton.style.setProperty('--hover-color', `hsl(${randomHue}, 75.00%, 75.00%)`);
    
    


    //randomize cached index
    doRandom();
    const id = loadVideo(cachedIndex);
    const time = loadTime(cachedIndex);

    player.loadVideoById({'videoId': id,
        'startSeconds': time});

    if (timerEnabled)
    {
        resetTimer(Number(timerInput.value));
    }
}

let timer = null;
function setTimer(duration)
{

    timerDisplay.textContent = `Time: ${duration}`;
    navTimer.textContent = `Time: ${duration}`;
    let durationCopy = duration;
    //count down
    timer = setInterval(() => {

        durationCopy--;
        timerDisplay.textContent = `Time: ${durationCopy}`;
        navTimer.textContent = `Time: ${durationCopy}`;
        if (durationCopy === 0 || timerEnabled == false)
        {
            clearInterval(timer);
            if (timerEnabled)
            {
                getRandomVideoAtRandomTime();
                setTimer(duration);
            } else {
                timerDisplay.textContent = `Timer disabled.`;
                navTimer.textContent = `Timer disabled.`;
            }

        }

    }, 1000)

    //getRandomVideoAtRandomTime();

}

function resetTimer(duration)
{
    clearInterval(timer);
    setTimer(duration);
    if (!timerEnabled)
    {
        timerDisplay.textContent = `Timer disabled.`;
        navTimer.textContent = `Timer disabled.`;
    }
}

function toggleTimer()
{
    timerEnabled = !timerEnabled;
    timerButton.classList.remove("disabled", "enabled");

    if (timerEnabled)
    {
        if (timer != null)
        {
            clearInterval(timer);
            timer = null;
            console.log("cleared timer");
        }

        const numInput = Number(timerInput.value);
        if (numInput >= 1 && !isNaN(numInput))
        {

            setTimer(Math.round(numInput));
        } else {
            timerDisplay.textContent = `Please input a valid time.`;
            navTimer.textContent = `Timer disabled.`;
        }

        timerButton.classList.add("enabled");
      
        
    } else {
        timerDisplay.textContent = `Timer disabled.`;
        navTimer.textContent = `Timer disabled.`;
        timerButton.classList.add("disabled");

    }
}
